        RAISE EXCEPTION 'SandIAM 0.9.7 revision045 indexes catalog differs from the exact reviewed structure';
    END IF;
    SELECT COALESCE(jsonb_agg(to_jsonb(captured)), '[]'::jsonb) INTO actual_catalog
    FROM (SELECT c.relname, t.tgname, regexp_replace(replace(replace(pg_get_triggerdef(t.oid, true), '::text[]', ''), '::text', ''), '[()[:space:]]', '', 'g') AS definition
            FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
            JOIN pg_trigger t ON t.tgrelid=c.oid
            WHERE n.nspname='public' AND left(c.relname, char_length('sand_iam')) = 'sand_iam' AND NOT t.tgisinternal
            ORDER BY c.relname,t.tgname) captured;
    IF actual_catalog IS DISTINCT FROM $iam097_triggers$[]$iam097_triggers$::jsonb THEN
        RAISE EXCEPTION 'SandIAM 0.9.7 revision045 triggers catalog differs from the exact reviewed structure';
    END IF;
    SELECT COALESCE(jsonb_agg(to_jsonb(captured)), '[]'::jsonb) INTO actual_catalog
    FROM (SELECT c.relname, p.polname, p.polcmd, p.polpermissive,
            regexp_replace(replace(replace(pg_get_expr(p.polqual,p.polrelid), '::text[]', ''), '::text', ''), '[()[:space:]]', '', 'g') AS using_expression,
            regexp_replace(replace(replace(pg_get_expr(p.polwithcheck,p.polrelid), '::text[]', ''), '::text', ''), '[()[:space:]]', '', 'g') AS check_expression
            FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
            JOIN pg_policy p ON p.polrelid=c.oid
            WHERE n.nspname='public' AND left(c.relname, char_length('sand_iam')) = 'sand_iam' ORDER BY c.relname,p.polname) captured;
    IF actual_catalog IS DISTINCT FROM $iam097_policies$[]$iam097_policies$::jsonb THEN
        RAISE EXCEPTION 'SandIAM 0.9.7 revision045 policies catalog differs from the exact reviewed structure';
    END IF;
    EXECUTE $iam097_menu_regroup$-- SandIAM top-level navigation regroup (parent_id and stored path only).
-- Three stable groups sit under the SandIAM root: 应用接入 / 用户与权限 / 高级.
-- Permission codes, slugs and components are unchanged; hidden entity pages
-- keep is_hidden=1 so they stay reachable but invisible in the sidebar. Moved
-- pages switch their stored path to the absolute route (for example
-- '/sand-iam/application') so the front-end hierarchical path join keeps every
-- effective URL identical; direct links to the old routes keep working. Every
-- statement is idempotent: re-running converges to the same tree without
-- duplicating menus or role links.

-- The groups are visible component-less menu nodes (type=2 with an empty
-- component). A directory row (type=1) would force the host layout component
-- '/index/index' on the nested level and render a second layout frame.
WITH group_def("name","code","path","sort") AS (
    VALUES
        ('应用接入','SandIAMGroupAccess','access',97),
        ('用户与权限','SandIAMGroupPeople','people',96),
        ('高级','SandIAMGroupAdvanced','advanced',20)
)
INSERT INTO "sand_system_menu"
    ("parent_id","name","code","slug","type","path","component","icon","sort","is_hidden","status","create_time","update_time")
SELECT root."id", group_def."name", group_def."code", '', 2, group_def."path", '', '', group_def."sort", 2, 1, NOW(), NOW()
FROM group_def
CROSS JOIN LATERAL (
    SELECT "id" FROM "sand_system_menu" WHERE "code" = 'SandIAM' ORDER BY "id" LIMIT 1
) root
WHERE NOT EXISTS (
    SELECT 1 FROM "sand_system_menu" existing WHERE existing."code" = group_def."code"
);

-- Moved pages keep their effective URL byte-for-byte: the stored path becomes
-- the absolute route, which the front-end path joiner returns unchanged
-- instead of prefixing it with the group path. is_hidden is not touched, so
-- hidden entity pages stay hidden.
UPDATE "sand_system_menu" menu
SET "parent_id" = grp."id",
    "path" = CASE WHEN menu."path" LIKE '/%' THEN menu."path" ELSE '/sand-iam/' || menu."path" END,
    "update_time" = NOW()
FROM "sand_system_menu" grp
WHERE grp."code" = 'SandIAMGroupAccess'
  AND menu."type" = 2
  AND menu."status" = 1
  AND menu."delete_time" IS NULL
  AND menu."code" IN (
      'SandIAMApplicationCapability','SandIAMApplication','SandIAMEnvironment',
      'SandIAMWorkload','SandIAMCredential','SandIAMGrant',
      'SandIAMApplicationNetworkPolicy'
  );

UPDATE "sand_system_menu" menu
SET "parent_id" = grp."id",
    "path" = CASE WHEN menu."path" LIKE '/%' THEN menu."path" ELSE '/sand-iam/' || menu."path" END,
    "update_time" = NOW()
FROM "sand_system_menu" grp
WHERE grp."code" = 'SandIAMGroupPeople'
  AND menu."type" = 2
  AND menu."status" = 1
  AND menu."delete_time" IS NULL
  AND menu."code" IN (
      'SandIAMPeopleAccess','SandIAMOrganization','SandIAMIdentity',
      'SandIAMIdentityBinding','SandIAMUserType','SandIAMIdentityUserType',
      'SandIAMRole','SandIAMIdentityRole','SandIAMIdentityGroup',
      'SandIAMIdentityInvitation','SandIAMIdentityImport'
  );

UPDATE "sand_system_menu" menu
SET "parent_id" = grp."id",
    "path" = CASE WHEN menu."path" LIKE '/%' THEN menu."path" ELSE '/sand-iam/' || menu."path" END,
    "update_time" = NOW()
FROM "sand_system_menu" grp
WHERE grp."code" = 'SandIAMGroupAdvanced'
  AND menu."type" = 2
  AND menu."status" = 1
  AND menu."delete_time" IS NULL
  AND menu."code" IN (
      'SandIAMConnection','SandIAMGettingStarted','SandIAMAuditTroubleshooting','SandIAMApiGovernance',
      'SandIAMAuthSession','SandIAMEventNotification','SandIAMService',
      'SandIAMServiceAction','SandIAMIdentityProvider','SandIAMResource',
      'SandIAMPolicy','SandIAMAdminScope','SandIAMAdminOrganizationGrant',
      'SandIAMAdminApplicationGrant','SandIAMAudit','SandIAMApplicationBusinessAction',
      'SandIAMApiResource','SandIAMApiRouteBinding','SandIAMRouteManifest',
      'SandIAMPolicySimulate','SandIAMAuthPolicy','SandIAMApplicationExperience',
      'SandIAMMessageProvider','SandIAMFederationConfig','SandIAMScimTokens',
      'SandIAMRadiusNas','SandIAMOAuthClient','SandIAMOAuthRegistrationToken',
      'SandIAMCasService','SandIAMDeveloperDocs','SandIAMSyncConnector',
      'SandIAMWebhook','SandIAMWebhookDelivery','SandIAMSecurityAlert',
      'SandIAMAuditRetentionPolicy','SandIAMInitialization'
  );

-- Roles holding a permission button under a regrouped page but missing the
-- page link receive it; seeds grant both, this only repairs drift.
INSERT INTO "sand_system_role_menu" ("role_id","menu_id")
SELECT DISTINCT role_menu."role_id", page."id"
FROM "sand_system_role_menu" role_menu
JOIN "sand_system_menu" permission ON permission."id" = role_menu."menu_id" AND permission."type" = 3
JOIN "sand_system_menu" page ON page."id" = permission."parent_id"
JOIN "sand_system_menu" grp ON grp."id" = page."parent_id"
WHERE grp."code" IN ('SandIAMGroupAccess','SandIAMGroupPeople','SandIAMGroupAdvanced')
  AND NOT EXISTS (
      SELECT 1 FROM "sand_system_role_menu" existing
      WHERE existing."role_id" = role_menu."role_id" AND existing."menu_id" = page."id"
  );

-- Roles that can already see a moved page also receive the group link, so the
-- group entry renders for them; superadministrators read every menu regardless.
INSERT INTO "sand_system_role_menu" ("role_id","menu_id")
SELECT DISTINCT role_menu."role_id", grp."id"
FROM "sand_system_role_menu" role_menu
JOIN "sand_system_menu" child ON child."id" = role_menu."menu_id"
JOIN "sand_system_menu" grp ON grp."id" = child."parent_id"
WHERE grp."code" IN ('SandIAMGroupAccess','SandIAMGroupPeople','SandIAMGroupAdvanced')
  AND NOT EXISTS (
      SELECT 1 FROM "sand_system_role_menu" existing
      WHERE existing."role_id" = role_menu."role_id" AND existing."menu_id" = grp."id"
  );

-- UX-P10 terminology pass: rename menus by stable code only. Fresh installs
-- already seed the new names from lifecycle/base.pgsql; these updates converge
-- upgraded installations to the same labels. Codes, slugs, paths, components,
-- sort and is_hidden are untouched, so permissions and routes are unaffected.
-- Every statement is idempotent: re-running writes the same name again.
UPDATE "sand_system_menu" SET "name" = '身份与权限（SandIAM）', "update_time" = NOW() WHERE "code" = 'SandIAM';
UPDATE "sand_system_menu" SET "name" = '首页', "update_time" = NOW() WHERE "code" = 'SandIAMOverview';
UPDATE "sand_system_menu" SET "name" = 'OAuth 授权接入', "update_time" = NOW() WHERE "code" = 'SandIAMOAuthClient';
UPDATE "sand_system_menu" SET "name" = 'OAuth 动态注册令牌', "update_time" = NOW() WHERE "code" = 'SandIAMOAuthRegistrationToken';
UPDATE "sand_system_menu" SET "name" = 'CAS 单点接入', "update_time" = NOW() WHERE "code" = 'SandIAMCasService';
UPDATE "sand_system_menu" SET "name" = '自动同步用户（SCIM）', "update_time" = NOW() WHERE "code" = 'SandIAMScimTokens';
UPDATE "sand_system_menu" SET "name" = '网络设备登录认证（RADIUS）', "update_time" = NOW() WHERE "code" = 'SandIAMRadiusNas';
-- WP-B1: the seven-step manual connection flow is demoted into 高级 as
-- 「手动接入」; the two-click 「开通功能」 page (SandIAMApplicationCapability,
-- seeded hidden by migration 046) takes over application capability grants.
UPDATE "sand_system_menu" SET "name" = '手动接入', "update_time" = NOW() WHERE "code" = 'SandIAMConnection';
$iam097_menu_regroup$;
    EXECUTE $iam097_default_app$-- SandIAM default application neutralization (0.9.6, tightened 0.9.7).
-- Releases before 0.9.6 auto-provisioned the first-use default application
-- inside the 'default' organization under one fixed product identity: a
-- fixed legacy code and display name (written below as SQL unicode escapes
-- because the release payload hygiene gate forbids industry literals; they
-- decode to exactly that retired pair). Recognition therefore requires the
-- complete legacy identity — default organization, exact legacy code and
-- name, an active application, the active prod/sand-ai/sand-ai provisioned
-- chain, no existing 'default-app' in the same organization, and exactly one
-- candidate. Manually registered or renamed applications, disabled rows,
-- scoped organizations and ambiguous multi-candidate states are all left
-- untouched; status is never resurrected and only code/name/update_time move.
-- Identifiers stay numeric, so environments, clients, grants, credentials,
-- audits and every external reference keep working unchanged. The statement
-- is idempotent: re-running converges to the same state.
WITH candidates AS (
    SELECT candidate."id"
    FROM "sand_iam_application" candidate
    JOIN "sand_iam_organization" org
      ON org."id" = candidate."organization_id"
    WHERE org."code" = 'default'
      AND org."delete_time" IS NULL
      AND candidate."code" = U&'\006C\0076\0078\0075'
      AND candidate."name" = U&'\5F8B\5E8F'
      AND candidate."status" = 1
      AND candidate."delete_time" IS NULL
      AND EXISTS (
          SELECT 1
          FROM "sand_iam_environment" env
          JOIN "sand_iam_workload_client" client
            ON client."environment_id" = env."id"
          WHERE env."application_id" = candidate."id"
            AND env."delete_time" IS NULL
            AND env."status" = 1
            AND env."code" = 'prod'
            AND client."delete_time" IS NULL
            AND client."status" = 1
            AND client."code" = 'sand-ai'
            AND client."audience" = 'sand-ai'
      )
      AND NOT EXISTS (
          SELECT 1
          FROM "sand_iam_application" existing
          WHERE existing."organization_id" = candidate."organization_id"
            AND existing."code" = 'default-app'
            AND existing."delete_time" IS NULL
      )
)
UPDATE "sand_iam_application" app
SET "code" = 'default-app',
    "name" = '默认应用',
    "update_time" = NOW()
FROM candidates
WHERE app."id" = candidates."id"
  AND (SELECT count(*) FROM candidates) = 1;
$iam097_default_app$;
END $sand_iam_upgrade_097$;

COMMIT;
